  cr.creative_format as creative_format,
  cr.call_to_action as call_to_action,
  null::varchar as conversion_tag,
  null::varchar as kpi_group,
  null::boolean as counts_toward_kpi,
  null::varchar as campaign_type,
  null::varchar as ga4_session_source,
  null::varchar as ga4_session_medium,
  null::varchar as ga4_session_campaign,
  null::varchar as province,
  null::varchar as product,
  null::varchar as segment,
  null::varchar as quality_band,
  null::varchar as line_type,
  null::varchar as goal_metric,
  f.currency_code as currency_code,
  f.loaded_from as loaded_from,
  coalesce(f.impressions, 0) as impressions,
  coalesce(f.clicks, 0) as clicks,
  coalesce(f.spend, 0) as spend,
  coalesce(f.video_starts, 0) as video_starts,
  coalesce(f.completed_plays, 0) as completed_plays,
  coalesce(f.post_shares, 0) as post_shares,
  coalesce(f.spots, 0) as spots,
  0 as conversions,
  0 as platform_conversions,
  0 as platform_all_conversions,
  0 as revenue,
  0 as click_through_conversions,
  0 as view_through_conversions,
  0 as sessions,
  0 as quotes,
  0 as quality_quotes,
  0 as binds,
  0 as customers,
  0 as performance_trials,
  0 as organic_trials,
  0 as scorecard_trials,
  0 as performance_flow_starts,
  0 as organic_flow_starts,
  0 as commuter_starts,
  0 as commuter_activations,
  0 as site_visits,
  0 as flight_searches,
  0 as flight_bookings,
  0 as hotel_searches,
  0 as hotel_bookings,
  0 as travel_search_signals,
  0 as attributed_books,
  0 as goal_value
from GOLD.MARTS.FCT_AD_DELIVERY_DAILY f
join GOLD.MARTS.DIM_DATE d on d.date_key = f.date_key
left join GOLD.MARTS.DIM_CAMPAIGN c on c.campaign_key = f.campaign_key
left join GOLD.MARTS.DIM_CLIENT cl on cl.client_code = coalesce(f.client_code, c.client_code)
left join GOLD.MARTS.DIM_SOURCE s on s.source_key = f.source_key
